/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface TickerPoint {
  /** Label for the scrubber: "10:30", "Oct 21". */
  t: string
  v: number
}

export type TickerSeries = (number | TickerPoint)[]

export interface TickerMarket {
  state: "open" | "closed" | "pre" | "post"
  /** "Closed at 16:00 EDT", "Opens 09:30". */
  label?: string
}

/** Every word the card shows or announces. Pass any of them through `labels` to translate. */
export interface TickerCardLabels {
  /** Spoken names for range keys such as "1D" or "YTD". */
  ranges: Record<string, string>
  range: string
  marketOpen: string
  preMarket: string
  afterHours: string
  marketClosed: string
  stale: string
  noHistory: string
  loading: (symbol?: string) => string
  unavailable: (symbol?: string) => string
  retry: string
  change: (direction: "up" | "down" | "flat", amount: string, percent: string) => string
  chart: (symbol: string | undefined, period: string, low: string, high: string) => string
}

export interface TickerCardProps extends Omit<React.ComponentProps<"div">, "children"> {
  symbol?: string
  name?: string
  /** "NASDAQ", "Coinbase". */
  exchange?: string
  /** Last price in `currency`. */
  price?: number
  currency?: string
  locale?: string
  /** Decimal places for prices. Defaults to 2, or more for prices under 1. */
  decimals?: number
  /** Yesterday's close. The 1D change and baseline use it. */
  previousClose?: number
  /** Price history per range, oldest first. Static: the card fetches nothing. */
  series?: Partial<Record<string, TickerSeries>>
  ranges?: string[]
  range?: string
  defaultRange?: string
  onRangeChange?: (range: string) => void
  market?: TickerMarket
  /** `true` or a note such as "Delayed 15 min". Shows in amber. */
  stale?: boolean | string
  /** "Updated 16:00 EDT". */
  updated?: string
  layout?: "full" | "compact"
  loading?: boolean
  error?: React.ReactNode
  onRetry?: () => void
  /** Translate or reword any text the card shows or announces. */
  labels?: Partial<TickerCardLabels>
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const DEFAULT_LABELS: TickerCardLabels = {
  ranges: {
    "1D": "Today",
    "5D": "Past 5 days",
    "1M": "Past month",
    "3M": "Past 3 months",
    "6M": "Past 6 months",
    YTD: "Year to date",
    "1Y": "Past year",
    "5Y": "Past 5 years",
    "24H": "Past 24 hours",
  },
  range: "Range",
  marketOpen: "Market open",
  preMarket: "Pre-market",
  afterHours: "After hours",
  marketClosed: "Market closed",
  stale: "Price may be out of date",
  noHistory: "No price history for this range",
  loading: (symbol) => `Loading quote${symbol ? ` for ${symbol}` : ""}`,
  unavailable: (symbol) => `Quote unavailable${symbol ? ` for ${symbol}` : ""}`,
  retry: "Try again",
  change: (direction, amount, percent) =>
    `${direction === "up" ? "up" : direction === "down" ? "down" : "unchanged"} ${amount}, ${percent}`,
  chart: (symbol, period, low, high) => `${symbol ?? "Price"}, ${period}: low ${low}, high ${high}`,
}

const toPoints = (s: TickerSeries | undefined): TickerPoint[] =>
  (s ?? [])
    .map((p, i) => (typeof p === "number" ? { t: String(i + 1), v: p } : p))
    .filter((p) => p && Number.isFinite(p.v))

/* -------------------------------------------------------------------------------------------------
 * TickerCard
 * -----------------------------------------------------------------------------------------------*/

const surface =
  "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) flex min-w-0 flex-col"

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

