/* -------------------------------------------------------------------------------------------------
 * Chart
 * -----------------------------------------------------------------------------------------------*/

const W = 600

const H = 120

/**
 * The price line in `--chatcn-chart-1` with a faint wash under it and, for one day, a dotted
 * previous close to measure against. Scrub with the pointer or the arrow keys: the header shows
 * the price at that point.
 */
function PriceChart({
  points,
  baseline,
  compact,
  scrub,
  onScrub,
  format,
  label,
}: {
  points: TickerPoint[]
  baseline?: number
  compact?: boolean
  scrub: number | null
  onScrub?: (index: number | null) => void
  format: (v: number) => string
  label: string
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  const values = points.map((p) => p.v)
  const lo = Math.min(...values, baseline ?? Number.POSITIVE_INFINITY)
  const hi = Math.max(...values, baseline ?? Number.NEGATIVE_INFINITY)
  const span = hi - lo || 1
  const pad = compact ? 3 : 8
  const x = (i: number) => (points.length > 1 ? (i / (points.length - 1)) * W : W / 2)
  const y = (v: number) => pad + (1 - (v - lo) / span) * (H - pad * 2)
  const d = points.map((p, i) => `${i ? "L" : "M"}${x(i).toFixed(2)},${y(p.v).toFixed(2)}`).join("")
  const area = `${d}L${W},${H}L0,${H}Z`
  const gradientId = React.useId()
  const active = scrub !== null ? points[scrub] : undefined

  const pick = (clientX: number) => {
    const rect = ref.current?.getBoundingClientRect()
    if (!rect || points.length < 2) return
    const f = (clientX - rect.left) / rect.width
    onScrub?.(Math.round(Math.max(0, Math.min(1, f)) * (points.length - 1)))
  }

  const interactive = !!onScrub && points.length > 1

  const visual = (
    <>
      <svg
        aria-hidden="true"
        viewBox={`0 0 ${W} ${H}`}
        preserveAspectRatio="none"
        className="absolute inset-0 size-full overflow-visible"
      >
        <defs>
          <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
            <stop
              offset="0%"
              stopColor="var(--chatcn-chart-1)"
              stopOpacity={compact ? 0.14 : 0.16}
            />
            <stop offset="100%" stopColor="var(--chatcn-chart-1)" stopOpacity="0" />
          </linearGradient>
        </defs>
        {points.length > 1 ? <path d={area} fill={`url(#${gradientId})`} /> : null}
        {baseline !== undefined && !compact ? (
          <line
            x1="0"
            x2={W}
            y1={y(baseline)}
            y2={y(baseline)}
            stroke="var(--chatcn-fg-faint)"
            strokeWidth="1"
            strokeDasharray="2 4"
            vectorEffect="non-scaling-stroke"
          />
        ) : null}
        <path
          d={d}
          fill="none"
          stroke="var(--chatcn-chart-1)"
          strokeWidth={compact ? 1.5 : 1.75}
          strokeLinecap="round"
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>
      {active && scrub !== null ? (
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 w-px -translate-x-1/2"
          style={{ left: `${(x(scrub) / W) * 100}%` }}
        >
          <span className="bg-(color:--chatcn-border-strong) absolute inset-y-0 w-px" />
          <span
            className="bg-(color:--chatcn-chart-1) ring-(color:--chatcn-card) absolute size-2 -translate-x-[3.5px] -translate-y-1/2 rounded-[2px] ring-2"
            style={{ top: `${(y(active.v) / H) * 100}%` }}
          />
        </span>
      ) : null}
    </>
  )
  const frame = cn("relative w-full select-none", compact ? "h-8" : "h-28")

  if (!interactive) {
    return (
      // Time runs left to right in every locale, so the chart never mirrors.
      <div ref={ref} dir="ltr" role="img" aria-label={label} className={frame}>
        {visual}
      </div>
    )
  }

  const shown = active ?? points[points.length - 1]
  return (
    <div
      ref={ref}
      dir="ltr"
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={points.length - 1}
      aria-valuenow={scrub ?? points.length - 1}
      aria-valuetext={shown ? `${shown.t}, ${format(shown.v)}` : undefined}
      onPointerMove={(e) => pick(e.clientX)}
      onPointerDown={(e) => pick(e.clientX)}
      onPointerLeave={() => onScrub?.(null)}
      onBlur={() => onScrub?.(null)}
      onKeyDown={(e) => {
        const last = points.length - 1
        const at = scrub ?? last
        let next: number | null | undefined
        if (e.key === "ArrowLeft") next = Math.max(0, at - 1)
        else if (e.key === "ArrowRight") next = Math.min(last, at + 1)
        else if (e.key === "Home") next = 0
        else if (e.key === "End") next = last
        else if (e.key === "Escape") next = null
        if (next !== undefined) {
          e.preventDefault()
          onScrub?.(next)
        }
      }}
      className={cn(frame, "chatcn-focus rounded-(--chatcn-radius-sm) cursor-crosshair touch-pan-y")}
    >
      {visual}
    </div>
  )
}

