/**
 * A stock or crypto quote: price, change in green or red with an arrow, a price line you can
 * scrub, ranges, market status and an amber note when the data is stale. Props only: the card
 * never fetches, so pass the series for each range.
 */
export function TickerCard({
  symbol,
  name,
  exchange,
  price,
  currency = "USD",
  locale = "en-US",
  decimals,
  previousClose,
  series,
  ranges = ["1D", "5D", "1M", "1Y"],
  range: rangeProp,
  defaultRange,
  onRangeChange,
  market,
  stale,
  updated,
  layout = "full",
  loading = false,
  error,
  onRetry,
  labels: labelsProp,
  className,
  ...props
}: TickerCardProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const rangeWord = (r: string) => labels.ranges[r] ?? DEFAULT_LABELS.ranges[r] ?? r
  const [rangeState, setRangeState] = React.useState(defaultRange ?? ranges[0] ?? "1D")
  const range = rangeProp ?? rangeState
  const [scrub, setScrub] = React.useState<number | null>(null)
  const compact = layout === "compact"
  const points = toPoints(series?.[range])

  const places =
    decimals ??
    (price !== undefined && Math.abs(price) < 1
      ? 4
      : price !== undefined && price >= 10_000
        ? 0
        : 2)
  const money = React.useMemo(() => {
    try {
      return new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        minimumFractionDigits: places,
        maximumFractionDigits: places,
      })
    } catch {
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: places,
        maximumFractionDigits: places,
      })
    }
  }, [locale, currency, places])
  const pct = React.useMemo(
    () =>
      new Intl.NumberFormat(locale, {
        style: "percent",
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
        signDisplay: "exceptZero",
      }),
    [locale],
  )

  if (error) {
    return (
      <div
        data-slot="ticker-card"
        data-ticker-state="error"
        role="alert"
        className={cn(surface, "gap-2 p-4", className)}
        {...props}
      >
        <div className="flex items-center gap-2">
          <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) size-4 shrink-0" />
          <span className="font-medium">{labels.unavailable(symbol)}</span>
        </div>
        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) ps-6 text-pretty">{error}</p>
        {onRetry ? (
          <Button size="sm" variant="outline" className="ms-6 self-start" onClick={onRetry}>
            <RotateCcwIcon />
            {labels.retry}
          </Button>
        ) : null}
      </div>
    )
  }

  if (loading || price === undefined) {
    return (
      <div
        data-slot="ticker-card"
        data-ticker-state="loading"
        aria-busy="true"
        className={cn(surface, compact && "flex-row items-center gap-4 p-3", className)}
        {...props}
      >
        <span className="sr-only">{labels.loading(symbol)}</span>
        {compact ? (
          <>
            <span aria-hidden="true" className="flex flex-1 flex-col gap-2">
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3.5 w-14" />
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-2.5 w-24" />
            </span>
            <span aria-hidden="true" className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-6 w-20" />
            <span aria-hidden="true" className="flex flex-col items-end gap-2">
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3.5 w-16" />
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-2.5 w-12" />
            </span>
          </>
        ) : (
          <div aria-hidden="true" className="flex flex-col gap-3 p-4">
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3 w-32" />
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-8 w-36" />
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3 w-24" />
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-sm) mt-2 h-28 w-full" />
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) h-7 w-48" />
          </div>
        )}
      </div>
    )
  }

  const oneDay = range === "1D" || range === "24H"
  const base = oneDay && previousClose !== undefined ? previousClose : points[0]?.v
  const active = scrub !== null ? points[scrub] : undefined
  const shown = active?.v ?? price
  const change = base !== undefined ? shown - base : undefined
  const ratio = change !== undefined && base ? change / base : undefined
  const dir = change === undefined || Math.abs(change) < 1e-9 ? "flat" : change > 0 ? "up" : "down"
  const tone =
    dir === "up"
      ? "text-(color:--chatcn-green)"
      : dir === "down"
        ? "text-(color:--chatcn-red)"
        : "text-(color:--chatcn-fg-subtle)"
  const Arrow = dir === "down" ? ArrowDownRightIcon : ArrowUpRightIcon
  const signed = (v: number) => `${v > 0 ? "+" : v < 0 ? "-" : ""}${money.format(Math.abs(v))}`
  const spokenChange =
    change !== undefined && ratio !== undefined
      ? labels.change(
          dir,
          money.format(Math.abs(change)),
          pct.format(Math.abs(ratio)).replace("+", ""),
        )
      : ""
  const period = active ? active.t : rangeWord(range)

  const changeLine =
    change !== undefined && ratio !== undefined ? (
      <span className={cn("inline-flex items-center gap-1 tabular-nums", tone)}>
        {dir === "flat" ? null : <Arrow aria-hidden="true" className="size-3.5 shrink-0" />}
        <span className="sr-only">{spokenChange}</span>
        <span aria-hidden="true">
          {signed(change)} ({pct.format(ratio)})
        </span>
      </span>
    ) : null

  const marketLine = market ? (
    <span
      className={cn(
        "inline-flex items-center gap-1.5",
        market.state === "open" ? "text-(color:--chatcn-green)" : "text-(color:--chatcn-fg-subtle)",
      )}
    >
      <span aria-hidden="true" className="size-1.5 rounded-[2px] bg-current" />
      {market.label ??
        (market.state === "open"
          ? labels.marketOpen
          : market.state === "pre"
            ? labels.preMarket
            : market.state === "post"
              ? labels.afterHours
              : labels.marketClosed)}
    </span>
  ) : null

  const staleNote = stale ? (
    <span className="text-(color:--chatcn-amber) inline-flex items-center gap-1">
      <ClockIcon aria-hidden="true" className="size-3.5 shrink-0" />
      {typeof stale === "string" ? stale : labels.stale}
    </span>
  ) : null

  const chartLabel = points.length
    ? labels.chart(
        symbol,
        rangeWord(range),
        money.format(Math.min(...points.map((p) => p.v))),
        money.format(Math.max(...points.map((p) => p.v))),
      )
    : ""

  if (compact) {
    return (
      <div
        data-slot="ticker-card"
        data-ticker-state={dir}
        data-layout="compact"
        className={cn(surface, "flex-row items-center gap-4 p-3 ps-4", className)}
        {...props}
      >
        <div className="flex min-w-0 flex-1 flex-col">
          <span className="font-medium tracking-tight">{symbol}</span>
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate">{name}</span>
        </div>
        {points.length > 1 ? (
          <div className="w-20 shrink-0 sm:w-24">
            <PriceChart
              points={points}
              compact
              scrub={null}
              format={money.format}
              label={chartLabel}
            />
          </div>
        ) : null}
        <div className="flex shrink-0 flex-col items-end text-end">
          <span className="font-medium tabular-nums">{money.format(price)}</span>
          {change !== undefined && ratio !== undefined ? (
            <span
              className={cn("text-[0.75rem]/[1rem] inline-flex items-center gap-0.5 tabular-nums", tone)}
            >
              {dir === "flat" ? null : <Arrow aria-hidden="true" className="size-3 shrink-0" />}
              <span className="sr-only">{spokenChange}</span>
              <span aria-hidden="true">{pct.format(ratio)}</span>
            </span>
          ) : null}
        </div>
      </div>
    )
  }

  return (
    <div
      data-slot="ticker-card"
      data-ticker-state={dir}
      data-layout="full"
      className={cn(surface, className)}
      {...props}
    >
      <div className="flex flex-col gap-1 px-4 pt-4">
        <div className="text-[0.8125rem]/[1.25rem] flex min-w-0 items-baseline gap-2">
          <span className="text-(color:--chatcn-fg) font-medium tracking-tight">{symbol}</span>
          {name ? <span className="text-(color:--chatcn-fg-subtle) min-w-0 truncate">{name}</span> : null}
          {exchange ? (
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) ms-auto shrink-0">
              {exchange}
            </span>
          ) : null}
        </div>
        <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
          <span className="text-[2rem]/[2.5rem] tracking-[-0.028em] text-(color:--chatcn-fg) leading-tight font-medium tracking-tight tabular-nums">
            {money.format(shown)}
          </span>
          <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] flex items-baseline gap-2">
            {changeLine}
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) tabular-nums">{period}</span>
          </span>
        </div>
      </div>

      <div className="px-4 pt-3">
        {points.length > 1 ? (
          <PriceChart
            points={points}
            baseline={oneDay ? previousClose : undefined}
            scrub={scrub}
            onScrub={setScrub}
            format={money.format}
            label={chartLabel}
          />
        ) : (
          <div className="rounded-(--chatcn-radius-sm) bg-(color:--chatcn-bg-subtle) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) flex h-28 flex-col items-center justify-center gap-1.5 text-center">
            <ChartLineIcon aria-hidden="true" className="size-4" />
            {labels.noHistory}
          </div>
        )}
      </div>

      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2 px-4 pt-3 pb-4">
        {ranges.length > 1 ? (
          <ToggleGroup
            value={[range]}
            onValueChange={(next) => {
              const picked = next[0]
              if (!picked) return
              setScrub(null)
              setRangeState(picked)
              onRangeChange?.(picked)
            }}
            aria-label={labels.range}
            className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) flex h-7 items-center gap-0.5 p-0.5 pointer-coarse:h-11"
          >
            {ranges.map((r) => (
              <Toggle
                key={r}
                value={r}
                aria-label={rangeWord(r) === r ? r : `${r}, ${rangeWord(r)}`}
                className={cn(
                  "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.75rem]/[1rem] inline-flex h-full min-w-9 items-center justify-center px-2 font-medium tabular-nums",
                  "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-standard) transition-[color,background-color,box-shadow] duration-150",
                  "hover:text-(color:--chatcn-fg) data-[pressed]:bg-(color:--chatcn-card) data-[pressed]:text-(color:--chatcn-fg) data-[pressed]:shadow-(--chatcn-shadow-xs)",
                )}
              >
                {r}
              </Toggle>
            ))}
          </ToggleGroup>
        ) : (
          <span />
        )}
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex flex-wrap items-center justify-end gap-x-2 gap-y-1">
          {marketLine}
          {staleNote ? (
            <>
              {marketLine ? <span aria-hidden="true">·</span> : null}
              {staleNote}
            </>
          ) : updated ? (
            <>
              {marketLine ? <span aria-hidden="true">·</span> : null}
              <span className="tabular-nums">{updated}</span>
            </>
          ) : null}
        </span>
      </div>
    </div>
  )
}

